//! Exact deterministic-serialization fixtures generated by the pinned TypeScript reference.

use std::error::Error;

use serde::Deserialize;
use signify_keri::serialization::{Sad, SadError, SerializationError, SerializedEvent};

const REFERENCE_SHA: &str = "ae92eceb8e776ad57669707bff7f84db9390b711";

#[derive(Debug, Deserialize)]
struct Fixture {
    schema_version: u8,
    upstream: String,
    reference_sha: String,
    generated_on: String,
    sources: Vec<String>,
    notes: String,
    blake3_prefix: String,
    cases: Vec<SerializationCase>,
    encoding_cases: Vec<EncodingCase>,
    rejected_cases: Vec<RejectedCase>,
    reference_quirks: ReferenceQuirks,
}

#[derive(Debug, Deserialize)]
struct SerializationCase {
    name: String,
    input_sad_json: String,
    raw: String,
    raw_hex: String,
    byte_size: usize,
    reference_size_accessor: usize,
    version_string: String,
    proto: String,
    kind: String,
    said: Option<String>,
    pre: Option<String>,
}

#[derive(Debug, Deserialize)]
struct EncodingCase {
    name: String,
    input_sad_json: String,
    raw: String,
    raw_hex: String,
}

#[derive(Debug, Deserialize)]
struct RejectedCase {
    name: String,
    reference_error_category: String,
    reference_error_message: String,
    rust_error_category: String,
}

#[derive(Debug, Deserialize)]
struct ReferenceQuirks {
    version_field_not_first: OrderQuirk,
    numeric_key_hoisting: NumericKeyQuirk,
    duplicate_field_last_wins: DuplicateQuirk,
    embedded_version_string_undersizes: EmbeddedVersionQuirk,
    utf16_size_accessor: Utf16Quirk,
    number_renormalization: NumberQuirk,
}

#[derive(Debug, Deserialize)]
struct OrderQuirk {
    input_sad_json: String,
    reference_raw: String,
    note: String,
    rust_error_category: String,
}

#[derive(Debug, Deserialize)]
struct NumericKeyQuirk {
    input_sad_json: String,
    reference_raw: String,
    note: String,
    rust_raw: String,
}

#[derive(Debug, Deserialize)]
struct DuplicateQuirk {
    input_raw: String,
    reference_reparsed: String,
    note: String,
    rust_error_category: String,
}

#[derive(Debug, Deserialize)]
struct EmbeddedVersionQuirk {
    input_sad_json: String,
    reference_raw: String,
    reference_byte_size: usize,
    reference_declared_size: String,
    note: String,
    rust_error_category: String,
}

#[derive(Debug, Deserialize)]
struct Utf16Quirk {
    raw: String,
    reference_size_accessor: usize,
    byte_size: usize,
    note: String,
}

#[derive(Debug, Deserialize)]
struct NumberQuirk {
    input_raw: String,
    reference_reparsed: String,
    note: String,
    rust_error_categories: Vec<String>,
}

fn fixture() -> Result<Fixture, Box<dyn Error>> {
    Ok(serde_json::from_str(include_str!(concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../fixtures/keri-serder/v1.json"
    )))?)
}

fn decode_hex(input: &str) -> Result<Vec<u8>, Box<dyn Error>> {
    if !input.len().is_multiple_of(2) {
        return Err("odd-length hexadecimal fixture field".into());
    }
    (0..input.len())
        .step_by(2)
        .map(|index| {
            input
                .get(index..index + 2)
                .ok_or_else(|| Box::<dyn Error>::from("hexadecimal fixture slice out of range"))
                .and_then(|pair| u8::from_str_radix(pair, 16).map_err(Into::into))
        })
        .collect()
}

fn serialization_error_category(error: &SerializationError) -> &'static str {
    match error {
        SerializationError::Sad { .. } => "Sad",
        SerializationError::MissingVersionField => "MissingVersionField",
        SerializationError::VersionFieldNotFirst { .. } => "VersionFieldNotFirst",
        SerializationError::Version { .. } => "Version",
        SerializationError::MessageTooLarge { .. } => "MessageTooLarge",
        SerializationError::SizeMismatch { .. } => "SizeMismatch",
        SerializationError::NonCanonicalEncoding => "NonCanonicalEncoding",
        SerializationError::UnexpectedFieldShape { .. } => "UnexpectedFieldShape",
        SerializationError::EventKind { .. } => "EventKind",
        SerializationError::Cesr { .. } => "Cesr",
        SerializationError::Crypto { .. } => "Crypto",
        _ => "Unknown",
    }
}

#[test]
fn fixture_metadata_matches_the_pinned_reference() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    assert_eq!(fixture.schema_version, 1);
    assert_eq!(fixture.upstream, "https://github.com/WebOfTrust/signify-ts.git");
    assert_eq!(fixture.reference_sha, REFERENCE_SHA);
    assert_ne!(fixture.generated_on, "");
    assert_eq!(fixture.sources, ["src/keri/core/serder.ts", "test/core/serder.test.ts"]);
    assert!(fixture.notes.contains("Prefixer"));
    // The pinned unit test asserts this Blake3 prefix, which proves the generator reproduced the
    // exact mutation sequence that produces the non-ASCII case.
    assert_eq!(fixture.blake3_prefix, "ECHOi6qRaswNpvytpCtpvEh2cB2aLAwVHBLFinno3YVW");
    Ok(())
}

#[test]
fn every_reference_message_serializes_byte_exactly() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    assert_eq!(fixture.cases.len(), 3);

    for case in &fixture.cases {
        let expected = decode_hex(&case.raw_hex)?;
        assert_eq!(expected, case.raw.as_bytes(), "case {} hex/text disagree", case.name);

        // Start from the reference's own field order, then size it exactly as `sizeify` does.
        let sad = Sad::from_json_bytes(case.input_sad_json.as_bytes())?;
        let event = SerializedEvent::from_sad(sad)?;
        assert_eq!(event.raw(), expected.as_slice(), "case {}", case.name);
        assert_eq!(event.size(), case.byte_size, "case {}", case.name);
        assert_eq!(
            event.sad().get_text("v"),
            Some(case.version_string.as_str()),
            "case {}",
            case.name
        );
        assert_eq!(event.protocol().as_str(), case.proto, "case {}", case.name);
        assert_eq!(event.serialization_kind().as_str(), case.kind, "case {}", case.name);

        // Parsing the reference bytes must reproduce the same value and the same bytes.
        let parsed = SerializedEvent::parse(&expected)?;
        assert_eq!(parsed, event, "case {}", case.name);
        assert_eq!(parsed.said(), case.said.as_deref(), "case {}", case.name);
        assert_eq!(parsed.identifier_prefix(), case.pre.as_deref(), "case {}", case.name);

        // The reference's `size` accessor counts UTF-16 units, so it agrees only for ASCII.
        let ascii_only = case.raw.is_ascii();
        assert_eq!(
            case.reference_size_accessor == case.byte_size,
            ascii_only,
            "case {} size-accessor agreement",
            case.name
        );
    }
    Ok(())
}

#[test]
fn escaping_and_value_shapes_round_trip_byte_exactly() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    assert_eq!(fixture.encoding_cases.len(), 2);

    for case in &fixture.encoding_cases {
        let expected = decode_hex(&case.raw_hex)?;
        assert_eq!(expected, case.raw.as_bytes(), "case {} hex/text disagree", case.name);

        let sad = Sad::from_json_bytes(case.input_sad_json.as_bytes())?;
        assert_eq!(sad.to_json_bytes()?, expected, "case {}", case.name);

        // Re-parsing our own output must be a fixed point.
        let reparsed = Sad::from_json_bytes(&expected)?;
        assert_eq!(reparsed, sad, "case {}", case.name);
        assert_eq!(reparsed.to_json_bytes()?, expected, "case {}", case.name);
    }
    Ok(())
}

#[test]
fn reference_rejections_map_to_stable_rust_error_categories() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    for case in &fixture.rejected_cases {
        assert_ne!(case.reference_error_category, "");
        assert_ne!(case.reference_error_message, "");
        match case.name.as_str() {
            "missing_version_field" => {
                assert_eq!(case.rust_error_category, "MissingVersionField");
                let sad = Sad::from_json_bytes(br#"{"t":"icp"}"#)?;
                assert!(matches!(
                    SerializedEvent::from_sad(sad),
                    Err(SerializationError::MissingVersionField)
                ));
            }
            "malformed_version_string" => {
                assert_eq!(case.rust_error_category, "Version");
                let sad = Sad::from_json_bytes(br#"{"v":"NOPE10JSON000000_","t":"icp"}"#)?;
                assert!(matches!(
                    SerializedEvent::from_sad(sad),
                    Err(SerializationError::Version { .. })
                ));
            }
            "unsupported_kind" => {
                assert_eq!(case.rust_error_category, "UnsupportedSerializationKind");
                // Rust makes a non-JSON kind unrepresentable: the version string parser is the
                // only way to name one, and it rejects every kind outside the pinned table.
                let sad = Sad::from_json_bytes(br#"{"v":"KERI10CBOR000000_"}"#)?;
                assert!(matches!(
                    SerializedEvent::from_sad(sad),
                    Err(SerializationError::Version { .. })
                ));
            }
            other => return Err(format!("unmapped rejected case {other}").into()),
        }
    }
    Ok(())
}

#[test]
fn reference_quirks_are_pinned_and_safely_diverged() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    let quirks = &fixture.reference_quirks;

    // 1. A version string that is not first still gets sized and emitted by the reference.
    let order = &quirks.version_field_not_first;
    assert_ne!(order.note, "");
    assert!(!order.reference_raw.starts_with(r#"{"v""#));
    let sad = Sad::from_json_bytes(order.input_sad_json.as_bytes())?;
    let error = SerializedEvent::from_sad(sad)
        .err()
        .ok_or("expected a field-order rejection")?;
    assert_eq!(serialization_error_category(&error), order.rust_error_category);

    // 2. JavaScript hoists array-index-like keys; insertion order is the protocol order.
    let numeric = &quirks.numeric_key_hoisting;
    assert_ne!(numeric.note, "");
    assert_ne!(numeric.reference_raw, numeric.rust_raw);
    let sad = Sad::from_json_bytes(numeric.input_sad_json.as_bytes())?;
    // Reading the reference's already-hoisted output reproduces it exactly; what Rust refuses to
    // do is re-order fields that arrive in protocol order.
    assert_eq!(sad.to_json_bytes()?, numeric.reference_raw.as_bytes());
    let mut protocol_order = Sad::new();
    protocol_order.insert("v", signify_keri::serialization::SadValue::text("KERI10JSON000000_"))?;
    protocol_order.insert("b", signify_keri::serialization::SadValue::Integer(1))?;
    protocol_order.insert("1", signify_keri::serialization::SadValue::Integer(2))?;
    protocol_order.insert("0", signify_keri::serialization::SadValue::Integer(3))?;
    assert_eq!(protocol_order.to_json_bytes()?, numeric.rust_raw.as_bytes());

    // 3. Duplicate labels are ambiguous; the reference silently keeps the last value.
    let duplicate = &quirks.duplicate_field_last_wins;
    assert_ne!(duplicate.note, "");
    assert!(duplicate.reference_reparsed.contains(r#""a":2"#));
    assert_eq!(duplicate.rust_error_category, "DuplicateField");
    assert!(matches!(
        Sad::from_json_bytes(duplicate.input_raw.as_bytes()),
        Err(SadError::DuplicateField { .. })
    ));

    // 4. A padded version string makes the reference's declared size overstate the message.
    let embedded = &quirks.embedded_version_string_undersizes;
    assert_ne!(embedded.note, "");
    assert_eq!(embedded.reference_declared_size, "KERI10JSON000027_");
    assert_eq!(0x27_usize, 39);
    assert_eq!(embedded.reference_byte_size, 35);
    assert_ne!(
        embedded.reference_byte_size, 0x27,
        "the reference declares a size it does not have"
    );
    let sad = Sad::from_json_bytes(embedded.input_sad_json.as_bytes())?;
    let error = SerializedEvent::from_sad(sad)
        .err()
        .ok_or("expected a version rejection")?;
    assert_eq!(serialization_error_category(&error), embedded.rust_error_category);
    // Rust also refuses to parse the message the reference produced, because its declared size
    // does not match its byte length.
    assert!(matches!(
        SerializedEvent::parse(embedded.reference_raw.as_bytes()),
        Err(SerializationError::SizeMismatch { .. })
    ));

    // 5. The reference's size accessor undercounts non-ASCII messages by design of JS strings.
    let utf16 = &quirks.utf16_size_accessor;
    assert_ne!(utf16.note, "");
    assert_eq!(utf16.byte_size, 313);
    assert_eq!(utf16.reference_size_accessor, 312);
    let parsed = SerializedEvent::parse(utf16.raw.as_bytes())?;
    assert_eq!(parsed.size(), utf16.byte_size);
    assert_eq!(usize::try_from(parsed.version_string().size())?, utf16.byte_size);

    // 6. Numbers renormalize through IEEE-754, changing bytes and therefore any SAID over them.
    let numbers = &quirks.number_renormalization;
    assert_ne!(numbers.note, "");
    assert_ne!(numbers.input_raw, numbers.reference_reparsed);
    assert!(numbers.rust_error_categories.contains(&"UnsupportedNumber".to_owned()));
    assert!(
        numbers
            .rust_error_categories
            .contains(&"IntegerOutOfRangeAt".to_owned())
    );
    assert!(matches!(
        Sad::from_json_bytes(numbers.input_raw.as_bytes()),
        Err(SadError::UnsupportedNumber { .. })
    ));
    assert!(matches!(
        Sad::from_json_bytes(br#"{"c":9007199254740993}"#),
        Err(SadError::IntegerOutOfRangeAt { .. })
    ));
    Ok(())
}
